const navy = Color(0xFF123A78);
const blue = Color(0xFF087DE5);
const teal = Color(0xFF19B7AD);
const red = Color(0xFFE20D19);
const ink = Color(0xFF172033);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await FirebaseBootstrap.initialize();
  runApp(const ResQMitraApp());
}

class ResQMitraApp extends StatelessWidget {
  const ResQMitraApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'ResQMitra', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, scaffoldBackgroundColor: const Color(0xFFF8FAFE),
      colorScheme: ColorScheme.fromSeed(seedColor: blue), fontFamily: 'Roboto',
      appBarTheme: const AppBarTheme(backgroundColor: Colors.white, foregroundColor: ink, elevation: 0)),
    home: const IntroScreen(),
  );
}

void go(BuildContext c, Widget page) => Navigator.push(c, MaterialPageRoute(builder: (_) => page));

class IntroScreen extends StatefulWidget { const IntroScreen({super.key}); @override State<IntroScreen> createState()=>_IntroScreenState(); }
class _IntroScreenState extends State<IntroScreen> {
  VideoPlayerController? controller; bool failed=false;
  @override void initState(){ super.initState(); controller=VideoPlayerController.asset('assets/video/resqmitra_intro.mp4')..initialize().then((_){ if(!mounted)return; setState((){}); controller!.setLooping(false); controller!.play(); controller!.addListener(_finish); }).catchError((_){if(mounted)setState(()=>failed=true);}); Future.delayed(const Duration(seconds: 8),_continue); }
  void _finish(){if(controller?.value.isInitialized==true && controller!.value.position>=controller!.value.duration && mounted)_continue();}
  void _continue(){if(!mounted)return; Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const RoleScreen()));}
  @override void dispose(){controller?.removeListener(_finish);controller?.dispose();super.dispose();}
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:Colors.white,body:Stack(fit:StackFit.expand,children:[if(controller?.value.isInitialized==true) FittedBox(fit:BoxFit.contain,child:SizedBox(width:controller!.value.size.width,height:controller!.value.size.height,child:VideoPlayer(controller!))) else Center(child:Image.asset('assets/images/resqmitra_logo.jpeg',width:270)), Positioned(bottom:30,left:24,right:24,child:TextButton(onPressed:_continue,child:const Text('Continue',style:TextStyle(color:navy))))]));
}

