class _AppreciationScreenState extends State<AppreciationScreen>{String badge='Hero Responder';final message=TextEditingController();@override void dispose(){message.dispose();super.dispose();}@override Widget build(BuildContext c)=>PageShell(title:'Appreciate Your Responder',child:ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.volunteer_activism,color:teal,size:64),const Text('Appreciate Your Responder',textAlign:TextAlign.center,style:TextStyle(fontSize:23,fontWeight:FontWeight.w900,color:navy)),const Text('Your responder was there when you needed help. Thank them for being a part of a safer community!',textAlign:TextAlign.center),const SizedBox(height:20),SectionCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Thank Your Responder',style:TextStyle(fontWeight:FontWeight.w900)),...['Hero Responder','Life Saver','First Aid Star','Kindness Badge'].map((b)=>InkWell(onTap:()=>setState(()=>badge=b),child:Padding(padding:const EdgeInsets.symmetric(vertical:8),child:Row(children:[Icon(badge==b?Icons.radio_button_checked:Icons.radio_button_off,color:badge==b?teal:Colors.black38),const SizedBox(width:10),Expanded(child:Text(b,style:const TextStyle(fontWeight:FontWeight.w600))),Icon(b=='Hero Responder'?Icons.military_tech:b=='Life Saver'?Icons.favorite:b=='First Aid Star'?Icons.medical_services:Icons.volunteer_activism,color:teal)]))))])),const Text('Share Feedback',style:TextStyle(fontWeight:FontWeight.w900)),const SizedBox(height:8),TextField(controller:message,maxLines:3,decoration:InputDecoration(hintText:'Write a thank-you message…',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)))),const SizedBox(height:15),PrimaryButton('SUBMIT',()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Thank-you badge selected. Connect backend to save feedback.')))),TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Skip for now'))]));}

class BackendSetupInfoScreen extends StatelessWidget {
  const BackendSetupInfoScreen({super.key});
  @override Widget build(BuildContext c)=>PageShell(title:'Live services setup',child:ListView(padding:const EdgeInsets.all(18),children:[
    const SectionCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
      Text('BACKEND STATUS',style:TextStyle(fontWeight:FontWeight.w900,color:navy)),SizedBox(height:8),
      Text('Firebase is not active until your own project is configured. This prototype will not send real responder alerts yet.'),
    ])),
    const SectionCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
      Text('NEXT CONFIGURATION STEPS',style:TextStyle(fontWeight:FontWeight.w900,color:navy)),SizedBox(height:8),
      Text('1. Create a Firebase project and enable Email/Password sign-in.\n2. Run flutterfire configure.\n3. Deploy firestore.rules and Cloud Functions.\n4. Configure a restricted Google Maps API key.\n5. Test location sharing and notifications on real devices.'),
    ])),
    const SectionCard(child:Text('Privacy: emergency contacts should remain in secure local storage unless the user explicitly consents to another handling method. Share live location only during an active help/response session. See BACKEND_SETUP.md in the project ZIP for complete instructions.')),
    PrimaryButton('OPEN RESPONDER DASHBOARD',()=>go(c,const ResponderScreen())),
  ]));
}

class HelplineScreen extends StatelessWidget {const HelplineScreen({super.key});final numbers=const [('112','All-in-one Emergency Response'),('100','Police'),('101','Fire & Rescue'),('102','Ambulance / National Ambulance Service'),('1091','Women Helpline'),('1098','Child Helpline'),('1930','Cyber Crime Helpline')];Future<void> call(String n)async{final uri=Uri(scheme:'tel',path:n);await launchUrl(uri);} @override Widget build(BuildContext c)=>PageShell(title:'Help Line',child:ListView(padding:const EdgeInsets.all(18),children:[const Text('Emergency contact numbers',style:TextStyle(fontSize:21,fontWeight:FontWeight.w900,color:navy)),const Text('Tap the phone icon to open your phone app.'),const SizedBox(height:14),...numbers.map((n)=>SectionCard(child:ListTile(leading:const CircleAvatar(backgroundColor:Color(0xFFE5F1FF),child:Icon(Icons.call,color:blue)),title:Text(n.$2,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text(n.$1,style:const TextStyle(color:navy,fontSize:17,fontWeight:FontWeight.w900)),trailing:IconButton(onPressed:()=>call(n.$1),icon:const Icon(Icons.phone_in_talk,color:teal,size:28))))) ]));}
